import{R as t,e as n,f as i,U as o}from"./chunks/framework.ywem4qy5.js";const d=JSON.parse('{"title":"Pipeliner","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/pipeliner.md","filePath":"integrations/crm/pipeliner.md","lastUpdated":1775908585000}'),r={name:"integrations/crm/pipeliner.md"};function a(l,e,s,p,h,c){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="pipeliner" tabindex="-1">Pipeliner <a class="header-anchor" href="#pipeliner" aria-label="Permalink to &quot;Pipeliner&quot;">​</a></h1><p>Follow the below steps to connect to the Pipeliner API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Pipeliner as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-pipeliner-api" tabindex="-1">Step 2. Connect to the Pipeliner API <a class="header-anchor" href="#step-2-connect-to-the-pipeliner-api" aria-label="Permalink to &quot;Step 2. Connect to the Pipeliner API&quot;">​</a></h3><ol><li>Go to <a href="https://www.pipelinersales.com/" target="_blank">Pipeliner</a> and login to your account.</li><li>In the top main menu, click on <strong>Menu</strong> icon in the far-left of the screen (9 dots).</li><li>In the top sub-menu, click on the <strong>Obtain API Key</strong>.</li><li>Copy the <strong>API Token</strong> from Pipeliner and paste in the <strong>API Token</strong> field in Formie.</li><li>Copy the <strong>API Password</strong> from Pipeliner and paste in the <strong>API Password</strong> field in Formie.</li><li>Copy the <strong>API Space ID</strong> from Pipeliner and paste in the <strong>API Space ID</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=t(r,[["render",a]]);export{d as __pageData,m as default};
